-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "esMX" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.mage.fire.Name"] = "Fuego"
L["rm.era.mage.fire.Description"] = "Fuego del nivel 10 al 60, elegida cuando tienes puntos en Fuego y ninguno en Escarcha, o cuando Fuego es tu árbol principal. Piroexplosión (si no, Bola de Fuego) abre el combate; Piroexplosión tras Presencia mental; Agostar mantiene cinco acumulaciones de Vulnerabilidad al fuego con Agostar mejorado sobre objetivos que vayan a sobrevivir; Explosión de Fuego y Agostar rematan; Bola de Fuego hace de relleno. Con tres o más enemigos trabados en combate: Ola explosiva, Fogonazo, Deflagración Arcana, Cono de frío, Ventisca. Recordatorios: Combustión con cinco acumulaciones de Agostar contra élites y en combates largos, armadura, Intelecto Arcano, gemas de maná, Barrera de hielo, Escudo de maná, Evocación, Contrahechizo, Eliminar maldición inferior, Bloque de hielo, Presencia mental. Desactivado por defecto: intercalar Explosión de Fuego siempre que esté lista."
L["rm.era.mage.fire.warcrafttavern.Name"] = "Fuego (Warcraft Tavern)"
L["rm.era.mage.fire.warcrafttavern.Description"] = "Fuego según Warcraft Tavern, una alternativa a la rotación integrada de Fuego recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Combustión se gasta al iniciar el combate contra élites y jefes en lugar de esperar a las acumulaciones de Agostar; Piroexplosión abre el combate; Agostar mantiene cinco acumulaciones con Agostar mejorado; Bola de Fuego hace de relleno; Explosión de Fuego solo en movimiento. Contra grupos de enemigos: primero Fogonazo, después Deflagración Arcana, Cono de frío y Ola explosiva de cerca, y Ventisca a distancia. Los mismos recordatorios que la rotación integrada de Fuego."
L["rm.era.mage.frost.Name"] = "Escarcha"
L["rm.era.mage.frost.Description"] = "Escarcha del nivel 1 al 60, también para builds de Arcano, y la opción predeterminada del mago antes de los talentos. Descarga de Escarcha (Bola de Fuego antes del nivel 4); Nova de Escarcha cuando un enemigo te alcanza, salvo contra jefes de banda; Misiles Arcanos una vez que un enemigo te alcanza si tienes Misiles arcanos mejorados; Cono de frío, Deflagración Arcana y Ventisca cuando hay tres o más enemigos trabados en combate; Explosión de Fuego en movimiento con maná de sobra; Explosión de Fuego y la varita rematan a enemigos normales en solitario; varita cuando te quedas sin maná. Recordatorios: armadura (Armadura de hielo en solitario, Armadura de mago en grupo, sin reemplazar nunca la que elegiste), Intelecto Arcano, conjurar y usar gemas de maná, Barrera de hielo, Escudo de maná, Evocación, Contrahechizo, Eliminar maldición inferior, Bloque de hielo, Mordedura de frío, Poder Arcano y Presencia mental. Desactivados por defecto: el Fogonazo de Trizar y la Descarga de Escarcha de rango 1 para acumular Escalofrío invernal. Traslación, Polimorfia, el kiteo y la elección de objetivo quedan a tu cargo."
L["rm.era.mage.frost.icyveins.Name"] = "Escarcha, farmeo en área (Icy Veins)"
L["rm.era.mage.frost.icyveins.Description"] = "Subida de nivel con Ventisca según la guía de farmeo en área de Icy Veins, elegida automáticamente cuando juegas en solitario con Ventisca mejorada. Desde dos enemigos trabados en combate: Nova de Escarcha sobre el grupo, Cono de frío mientras Nova se recarga, Ventisca una vez que no tienes nada al lado y Deflagración Arcana cuando sí; Descarga de Escarcha contra un solo objetivo, y Explosión de Fuego y la varita para rematar. Escudo de maná y Barrera de hielo se ponen antes de cada combate. Reunir al grupo de enemigos, Traslación y el kiteo quedan a tu cargo."
L["rm.forever.mage.arcane.Name"] = "Arcano"
L["rm.forever.mage.arcane.Description"] = "Arcano una vez que Arcano es tu árbol de talentos principal con 11 puntos y conoces Explosión Arcana. Inicia el combate con Descarga de Escarcha en solitario o Explosión Arcana en grupo; después Misiles Arcanos con Tromba de misiles, Explosión Arcana con Lanzamiento libre, Cólera Arcana con tres acumulaciones de Explosión Arcana, Explosión Arcana hasta cuatro acumulaciones contra élites y dos contra otros objetivos mientras puedas permitírtelo (el maná está oculto en Forever), después Descarga de Pirofrío, Descarga de Escarcha o Bola de Fuego para buscar Tromba de misiles, y una varita en solitario cuando no puedes permitirte un hechizo. Sin Cólera Arcana (el diseño anterior de la beta), Explosión de Fuego gasta las acumulaciones. En movimiento: Explosión de Fuego. Con tres o más enemigos luchando contra ti: Deflagración Arcana. Recordatorios: Presencia mental y Poder Arcano contra élites (Poder Arcano ya no espera a que tengas la mitad del maná), además de los recordatorios de mantenimiento del mago."
L["rm.forever.mage.fire.Name"] = "Fuego"
L["rm.forever.mage.fire.Description"] = "Fuego una vez que Fuego es tu árbol de talentos principal con 11 puntos (el nivel de Piroexplosión). Inicia el combate con Piroexplosión contra élites y, si no, con Descarga de Pirofrío o Bola de Fuego; después Piroexplosión con tres acumulaciones de Calentamiento, Lanza de hielo con Dedos de Escarcha o sobre un objetivo congelado (híbridos de Fuego/Escarcha), Explosión de Fuego cada vez que esté disponible, Agostar para mantener tus cinco acumulaciones de Vulnerabilidad al fuego contra élites, Descarga de Pirofrío (desde el 40) o Bola de Fuego, y varita en solitario cuando no puedes permitirte un hechizo. En movimiento: Explosión de Fuego o Lanza de hielo. Con cuatro o más enemigos luchando contra ti: Fogonazo, Ola explosiva y Deflagración Arcana. Agostar empieza a acumular solo cuando tienes Agostar mejorado; un Agostar a corta distancia está desactivado hasta que lo actives. Recordatorios: Combustión y Presencia mental contra élites, además de los recordatorios de mantenimiento del mago."
L["rm.forever.mage.fire.icyveins.Name"] = "Fuego para subir de nivel (Icy Veins)"
L["rm.forever.mage.fire.icyveins.Description"] = "La build de Fuego para subir de nivel de Icy Veins sin Agostar mejorado, una alternativa a la rotación integrada de Fuego recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Inicia el combate con Piroexplosión, usa Explosión de Fuego para gastar Despertar del fuego, Agostar mientras el enemigo se acerca (la salud del objetivo está oculta en Forever, así que rematar objetivos con poca salud queda a tu criterio), y después Descarga de Pirofrío (desde el 40) o Bola de Fuego. La misma área, movimiento, varita y recordatorios que la rotación integrada de Fuego, sin Combustión ni Presencia mental."
L["rm.forever.mage.frost.Name"] = "Escarcha"
L["rm.forever.mage.frost.Description"] = "Escarcha del nivel 1 al 60, y la opción predeterminada del mago de Forever antes de los hechizos de talento (Bola de Fuego hasta Descarga de Escarcha a nivel 4). Inicia el combate con Descarga de Escarcha; después Lanza de hielo con Dedos de Escarcha o sobre un objetivo congelado (también mientras aún se lanza Descarga de Escarcha, para cancelarla o agruparlas), Cono de frío con cinco acumulaciones de Escalofrío invernal, Misiles Arcanos con Tromba de misiles, Descarga de Escarcha y una varita en solitario cuando no puedes permitirte Descarga de Escarcha. En movimiento: Lanza de hielo; si no, Explosión de Fuego. Con tres o más enemigos luchando contra ti: Cono de frío; con cinco o más: Ventisca, o Deflagración Arcana si un enemigo te está atacando. Se incluye el área de Fogonazo y Deflagración Arcana de Warcraft Tavern, pero desactivada. Recordatorios: Intelecto Arcano, armadura (de hielo o de escarcha en solitario, Armadura de mago en grupo, sin sustituir nunca la que hayas elegido), Barrera de hielo, Contrahechizo, Eliminar maldición inferior, Nova de Escarcha cuando un enemigo te alcanza y Mordedura de frío. En Forever la salud y el maná están ocultos para los addons, así que rematar objetivos con poca salud con Explosión de Fuego, Evocación y Bloque de hielo quedan a tu criterio; Traslación, el kiteo, Polimorfia y las gemas de maná también quedan a tu cargo."
L["rm.mop.mage.arcane.Name"] = "Recomendada"
L["rm.mop.mage.arcane.Description"] = "Recomendada para Arcano, del nivel 10 al 90 (seleccionada en la especialización Arcano). Explosión Arcana acumula cuatro cargas Arcanas; con cuatro, una activación de ¡Misiles Arcanos! se gasta con Misiles y, sin ella, sale Tromba Arcana en cuanto tu maná baja del 90 %. Por encima del 95 % de maná sigue con Explosión, que es como lo juega el simulador. Nunca deja Misiles con dos activaciones acumuladas, Tromba se lanza antes de que Alterar el tiempo te devuelva atrás y, con dos o más enemigos, Tromba sale cada cuatro cargas; Cono de frío y Deflagración Arcana cuando hay cinco cerca. Mantiene tu bomba de talento, y Explosión de Fuego o Lanza de hielo en movimiento sin Témpanos de hielo. Recordatorios: Poder Arcano y Alterar el tiempo con cuatro cargas y una activación, Armadura de Escarcha (de arrabio antes del 54), Luminosidad Arcana, Contrahechizo, Gema de maná, Reflejo exacto, Barrera de hielo, Témpanos de hielo, Runa de poder o Invocación. Distorsión temporal, Robar hechizo y Presencia mental están desactivados; Runa de poder sigue necesitando colocarse a mano."
L["rm.mop.mage.arcane.icyveins.Name"] = "Tromba con cuatro cargas (Icy Veins)"
L["rm.mop.mage.arcane.icyveins.Description"] = "La regla de Arcano de las guías (Icy Veins, Wowhead, Method, wowtbc.gg), una alternativa a la rotación integrada de Arcano recomendada: con cuatro cargas Arcanas, Misiles Arcanos si hay una activación y, si no, Tromba Arcana, sea cual sea tu maná; Misiles solo con cuatro cargas. Todo lo demás (Alterar el tiempo, bombas, área de efecto, movimiento, recordatorios) coincide con la recomendada, salvo que Poder Arcano se sugiere con cuatro cargas sin esperar a una activación. Desactivada por defecto: actívala y desactiva la rotación integrada de Arcano recomendada, o súbele la prioridad."
L["rm.mop.mage.fire.Name"] = "Recomendada"
L["rm.mop.mage.fire.Description"] = "Recomendada para Fuego, del nivel 10 al 90 (seleccionada en la especialización Fuego). Abre con una Piroexplosión lanzada completa; después, Explosión infernal (Explosión de Fuego antes del 24) convierte Calentamiento en una activación de ¡Piroexplosión!, que se lanza de inmediato salvo que Combustión esté a punto de estar disponible; luego espera al siguiente Calentamiento mientras lanzas Bola de Fuego. Combustión se activa justo después de una Piroexplosión mientras Ignición y la quemadura de Piroexplosión estén en el objetivo; el addon no puede ver cuán grande es Ignición, así que juzga tú si es débil. Mantiene tu bomba de talento, extiende con Explosión infernal cuando dos o más enemigos luchan contra ti, Cono de frío y Deflagración Arcana contra cinco cercanos, y Agostar en movimiento. Recordatorios: Armadura de arrabio, Presencia mental, Alterar el tiempo con ambas activaciones, Gema de maná, Luminosidad Arcana, Contrahechizo, Reflejo exacto, Barrera de hielo, Témpanos de hielo, Invocación o Runa de poder. Aliento de dragón, Distorsión temporal y Robar hechizo están desactivados."
L["rm.mop.mage.fire.icyveins.Name"] = "Retener ¡Piroexplosión! (Icy Veins)"
L["rm.mop.mage.fire.icyveins.Description"] = "El Fuego de Icy Veins, Method y wowtbc.gg, una alternativa a la rotación integrada de Fuego recomendada: una activación de ¡Piroexplosión! se retiene hasta que se le une un Calentamiento, y entonces se lanza junto con tu Bola de Fuego; solo se gasta sola cuando está a punto de expirar. Todo lo demás coincide con la recomendada. Desactivada por defecto: actívala y desactiva la rotación integrada de Fuego recomendada, o súbele la prioridad."
L["rm.mop.mage.frost.Name"] = "Recomendada"
L["rm.mop.mage.frost.Description"] = "Escarcha del nivel 10 al 90 (seleccionada en la especialización Escarcha). Lanza de hielo con dos Dedos de Escarcha, Descarga de Pirofrío con Congelación cerebral, tu bomba de talento, Orbe congelado, Lanza de hielo con un Dedos de Escarcha, Descarga de Escarcha; desde el 87 se retiene una activación para Alterar el tiempo cuando le faltan menos de 10 segundos. Con dos o más enemigos: Orbe congelado, Cono de frío y Deflagración Arcana cuando están cerca, y Ventisca cuando cuatro se quedan quietos. Lanza de hielo y Explosión de Fuego en movimiento sin Témpanos de hielo. Recordatorios: elemental de agua, Congelar contra cualquier cosa salvo un jefe (colócalo tú), Venas heladas sincronizado con Alterar el tiempo, Alterar el tiempo con dos Dedos de Escarcha en Venas heladas, Armadura de Escarcha (de arrabio antes del 54), Gema de maná, Luminosidad Arcana, Contrahechizo, Reflejo exacto, Barrera de hielo, Témpanos de hielo, Invocación o Runa de poder. Mordedura de frío, Presencia mental, Distorsión temporal y Robar hechizo están desactivados."
L["rm.mop.mage.unspecialized.Name"] = "Antes de una especialización"
L["rm.mop.mage.unspecialized.Description"] = "Para los niveles 1 a 9 y cualquier mago que aún no haya elegido especialización. Descarga de Pirofrío, Explosión de Fuego para rematar a un objetivo o en movimiento, Lanza de hielo en movimiento una vez aprendida, y Deflagración Arcana cuando hay tres o más enemigos al alcance cuerpo a cuerpo. Recordatorios: Nova de Escarcha cuando un enemigo te alcanza, Contrahechizo, y Armadura de arrabio y Luminosidad Arcana si llegas a ellas. Elegir una especialización al nivel 10 cambia a la rotación integrada de esa especialización."
L["rm.retail.mage.arcane.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.mage.arcane.Description"] = "Recomendada para Arcano. Resalta el próximo hechizo que sugiere el Asistente de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight; espera mientras lanzas o canalizas. Junto a él, recordatorios de lo que el Asistente de combate deja a tu cargo: Oleada arcana en combate, Intelecto arcano fuera de combate, Contrahechizo ante un lanzamiento interrumpible, Barrera prismática siempre que esté disponible en combate y tu habilidad racial en combate. Los lanzamientos enemigos están ocultos en combate, así que Contrahechizo solo se ilumina donde el juego los muestra; la salud está oculta en Retail, así que Bloque de hielo y otros botones de emergencia quedan a tu criterio. Reflejo exacto, Alterar el tiempo, Traslación y los abalorios quedan a tu cargo."
L["rm.retail.mage.arcane.guide.Name"] = "De referencia (Icy Veins y SimulationCraft)"
L["rm.retail.mage.arcane.guide.Description"] = "Solo de referencia, desactivada por defecto: la prioridad de Arcano de las guías. Andanada arcana y Lanzamiento libre están ocultos para los addons en el combate de Midnight (solo las cargas Arcanas siguen visibles), así que no puede funcionar allí; el maná está oculto en Retail, así que la Evocación con poco maná queda a tu cargo; léela o duplícala para experimentar. Inicia el combate con Explosión Arcana. Furia del Sol: Misiles Arcanos con Lanzamiento libre por debajo de 12 acumulaciones de Andanada, Descarga prismática fuera de Alma arcana, Tromba Arcana con cuatro cargas y, además, 12 de Andanada con Lanzamiento libre o 25 de Andanada, o con Alma arcana con cualquier número de cargas, Descarga prismática, Orbe Arcano con menos de tres cargas, Pulso arcano contra tres enemigos o sin cargas, Explosión Arcana. Lanzahechizos (con Hechicería astillada aprendida): Descarga prismática, Orbe contra grupos de enemigos, Tromba con 20 de Andanada (solo con cuatro cargas contra dos o más enemigos), Misiles con Lanzamiento libre por debajo de 15 de Andanada, Orbe y Pulso con menos de tres cargas (sin Pulso durante Oleada arcana), Explosión Arcana. Tromba Arcana cuando no se puede lanzar Explosión. Recordatorios: Oleada arcana, Toque del Magi tras una Tromba o una Descarga prismática durante Oleada o mucho antes de ella, Presencia mental sin cargas tras una Tromba, además de los recordatorios de la rotación integrada del Asistente de combate."
L["rm.retail.mage.fire.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.mage.fire.Description"] = "Recomendada para Fuego. Resalta el próximo hechizo que sugiere el Asistente de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight; espera mientras lanzas o canalizas. Junto a él, recordatorios de lo que el Asistente de combate deja a tu cargo: Combustión en combate, Intelecto arcano fuera de combate, Contrahechizo ante un lanzamiento interrumpible, Barrera flameante siempre que esté disponible en combate y tu habilidad racial en combate. Los lanzamientos enemigos están ocultos en combate, así que Contrahechizo solo se ilumina donde el juego los muestra; la salud está oculta en Retail, así que Bloque de hielo y otros botones de emergencia quedan a tu criterio."
L["rm.retail.mage.fire.guide.Name"] = "De referencia (Icy Veins, Wowhead y SimulationCraft)"
L["rm.retail.mage.fire.guide.Description"] = "Solo de referencia, desactivada por defecto: la prioridad de Fuego de las guías. Una buena racha, Calentamiento, Piroestruendo y las cargas de Explosión de Fuego están ocultos en el combate de Midnight, así que no puede funcionar allí. Explosión de Fuego mientras termina un lanzamiento para convertir Calentamiento en Una buena racha; inicia el combate con Piroexplosión. Piroexplosión (Fogonazo contra cuatro o más enemigos) con Hipertermia, Meteorito, Piroexplosión con Una buena racha, Explosión de Fuego con Calentamiento dentro de Combustión, Piroexplosión con Piroestruendo, Agostar con Resplandor de calor o en movimiento, Explosión de Fuego con Calentamiento y, después, Descarga de pirofrío o Bola de Fuego. Recordatorios: Combustión al terminar un lanzamiento con tiempo de lanzamiento, Barrera flameante y los recordatorios de utilidad. Esperar a Encendedor y hacer coincidir Meteorito con Combustión quedan a tu cargo."
L["rm.retail.mage.frost.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.mage.frost.Description"] = "Recomendada para Escarcha. Resalta el próximo hechizo que sugiere el Asistente de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight; espera mientras lanzas o canalizas. Junto a él, recordatorios de lo que el Asistente de combate deja a tu cargo: Invocar elemental de agua cuando tienes el talento y ningún elemental, Intelecto arcano fuera de combate, Contrahechizo ante un lanzamiento interrumpible, Barrera de hielo siempre que esté disponible en combate y tu habilidad racial en combate. Los lanzamientos enemigos están ocultos en combate, así que Contrahechizo solo se ilumina donde el juego los muestra; la salud está oculta en Retail, así que Bloque de hielo y otros botones de emergencia quedan a tu criterio."
L["rm.retail.mage.frost.guide.Name"] = "De referencia (Icy Veins y SimulationCraft)"
L["rm.retail.mage.frost.guide.Description"] = "Solo de referencia, desactivada por defecto: la prioridad de Escarcha de las guías para cada árbol de héroe. Las activaciones, las acumulaciones de Congelamiento y los tiempos de reutilización están ocultos en el combate de Midnight, así que no puede funcionar allí. Inicia el combate con Descarga de pirofrío o Descarga de Escarcha. Pirofrío (con Descarga de pirofrío aprendida): Pica glacial cuando está lista, Tormenta de cometas contra uno o dos enemigos, Aluvión con Congelación cerebral sin Vacío térmico, Lanza de hielo con dos acumulaciones de Dedos de Escarcha, Rayo de Escarcha, Orbe congelado, Ventisca con Lluvia helada contra tres enemigos, Lanza de hielo con Dedos de Escarcha si tienes Vacío térmico o con doce de Congelamiento, Aluvión, Nova de hielo o Cono de frío contra cinco y, después, Pica glacial o Descarga de pirofrío. Lanzahechizos: Tormenta de cometas, Aluvión con Congelación cerebral, Lanza de hielo con dos Dedos, Orbe congelado, Pica glacial cuando está lista, Ventisca con Lluvia helada, Lanza de hielo con Dedos de Escarcha o con seis de Congelamiento, Rayo de Escarcha, Aluvión, Nova de hielo o Cono de frío contra cuatro, Ventisca contra siete y, después, Pica glacial o Descarga de Escarcha. Lanza de hielo en movimiento. Recordatorios: Invocar elemental de agua, Barrera de hielo y los recordatorios de utilidad."
L["rm.retail.mage.initial.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.mage.initial.Description"] = "Recomendada antes de elegir una especialización (mientras el juego informa de la especialización inicial del mago). Resalta el próximo hechizo que sugiere el Asistente de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight; espera mientras lanzas o canalizas. Junto a él, los recordatorios que comparten todas las rotaciones integradas de mago, cada uno una vez que conoces su hechizo. Cuando elijas una especialización al nivel 10, tomarán el relevo las rotaciones integradas de esa especialización."
L["rm.sod.mage.arcane.Name"] = "Arcano (SoD)"
L["rm.sod.mage.arcane.Description"] = "Daño de Arcano en Temporada de descubrimiento, elegida cuando Arcano es tu árbol principal y tienes grabada la runa Explosión Arcana. Misiles Arcanos con Tromba de misiles; Tromba Arcana con cuatro acumulaciones de Explosión Arcana; Descarga de fuego fardo cuando sea seguro, nunca con cuatro o más acumulaciones de fuego fardo; Llama viva cada vez que esté disponible; Explosión Arcana hace de relleno. Tromba Arcana y Explosión de Fuego en movimiento; Llama viva y Deflagración Arcana contra grupos de enemigos. Recordatorios: Poder Arcano contra élites y en combates largos, Presencia mental con Poder Arcano o en movimiento, Venas heladas, Mordedura de frío y los demás recordatorios de mago."
L["rm.sod.mage.fire.Name"] = "Fuego (SoD)"
L["rm.sod.mage.fire.Description"] = "Fuego en Temporada de descubrimiento del nivel 1 al 60, y allí la opción predeterminada del mago. Usa las runas que tengas grabadas: Piroexplosión con Una buena racha de inmediato; Bomba viva mantenida sobre objetivos que vayan a sobrevivir; Agostar con Agostar mejorado mientras Vulnerabilidad al fuego tenga menos de dos acumulaciones o esté a punto de desaparecer; Llama viva cada vez que esté disponible; Descarga de fuego fardo con cinco acumulaciones de Vulnerabilidad al fuego, nunca con cuatro o más acumulaciones de fuego fardo (la quinta te mata); Descarga de Pirofrío y, si no, Bola de Fuego. Bomba viva, Llama viva y Explosión de Fuego en movimiento; Llama viva, Bomba viva, Ola explosiva, Cono de frío, Fogonazo y Ventisca contra grupos de enemigos. Recordatorios: Explosión de Fuego con Recalentamiento, Combustión, Venas heladas y Mordedura de frío, Armadura de arrabio u otra armadura, Intelecto Arcano, gemas de maná, Barrera de hielo, Escudo de maná, Evocación, Contrahechizo, eliminar maldiciones, Bloque de hielo. Extender Bomba viva entre objetivos queda a tu cargo."
L["rm.sod.mage.frost.Name"] = "Escarcha (SoD)"
L["rm.sod.mage.frost.Description"] = "Escarcha en Temporada de descubrimiento desde el nivel 10, elegida cuando Escarcha es tu árbol principal. Dedos de Escarcha se gasta en Lanza de hielo con tres o más de tus acumulaciones de Helar y, si no, en Congelación profunda; Descarga de fuego fardo con una activación de Congelación cerebral y, si no, cuando sea seguro, nunca con cuatro o más acumulaciones de fuego fardo; Bomba viva y Llama viva cuando estén grabadas; Descarga de fríoarcano y, si no, Descarga de Pirofrío y, si no, Descarga de Escarcha. Lanza de hielo, Orbe congelado, Bomba viva y Explosión de Fuego en movimiento; Orbe congelado, Llama viva, Bomba viva, Ventisca y Cono de frío contra grupos de enemigos. Recordatorios: Orbe congelado, Venas heladas, Mordedura de frío, armadura, gemas de maná y los demás recordatorios de mago. Encolar un hechizo mientras impacta una descarga queda a tu cargo."
L["rm.sod.mage.frost.warcrafttavern.Name"] = "Escarcha, runas de Fuego (SoD, Warcraft Tavern)"
L["rm.sod.mage.frost.warcrafttavern.Description"] = "La build de Escarcha de la fase 4 de Warcraft Tavern con runas de Fuego, una alternativa a la rotación integrada de Escarcha de Temporada de descubrimiento recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Piroexplosión abre el combate; Piroexplosión con Una buena racha; Bomba viva siempre activa; Agostar hasta cinco acumulaciones con Agostar mejorado; Descarga de fuego fardo solo con una activación de Congelación cerebral y nunca con cuatro o más acumulaciones de fuego fardo; Descarga de Pirofrío hace de relleno. Bomba viva y Explosión de Fuego en movimiento; Bomba viva, Cono de frío y Ventisca contra grupos de enemigos. Recordatorios: Explosión de Fuego con Recalentamiento, Orbe congelado durante Venas heladas, Venas heladas, Mordedura de frío y los demás recordatorios de mago."
L["rm.sod.mage.healer.Name"] = "Sanador (SoD)"
L["rm.sod.mage.healer.Description"] = "Sanación de mago en Temporada de descubrimiento, elegida cuando tienes grabada la runa Regeneración o Regeneración en masa. Con un objetivo amistoso: Retroceder en el tiempo y Preservación cronoestática por debajo de la mitad de la salud, Regeneración cuando falta tu Faro temporal, Regeneración en masa, Anomalía temporal. Con un objetivo enemigo, daño que sana a tus faros: Descarga de fríoarcano para sanadores de Escarcha y, si no, Misiles Arcanos con Tromba de misiles, Tromba Arcana con dos acumulaciones de Explosión Arcana, Descarga de fuego fardo cuando sea seguro (nunca con cuatro o más acumulaciones de fuego fardo) y Explosión Arcana. Recordatorios: Poder Arcano, Presencia mental, Orbe congelado y los demás recordatorios de mago. Desactivados por defecto: Deflagración Arcana contra grupos de enemigos, y Lanza de hielo y Congelación profunda para sanadores de Escarcha. Mientras canalizas Regeneración en masa ya se muestra el siguiente hechizo, así que puedes cancelarla de inmediato (su sanación directa es pequeña). Elegir a quién sanar queda a tu cargo."
L["rm.tbc.mage.arcane.Name"] = "Arcano"
L["rm.tbc.mage.arcane.Description"] = "Arcano, elegida cuando Arcano es tu árbol de talentos principal. Antes del nivel 64: Misiles Arcanos, con Descarga de Escarcha cuando escasea el maná. Desde el 64: Explosión Arcana mientras quemas maná (Poder Arcano, Ansia de sangre o más del 35 % de maná); si no, tres acumulaciones de Explosión Arcana y Descarga de Escarcha hasta que estén a punto de desaparecer. Deflagración Arcana y Cono de frío contra tres o más enemigos. Los recordatorios incluyen Poder Arcano, Presencia mental, gema de maná y Evocación."
L["rm.tbc.mage.fire.icyveins.Name"] = "Fuego (Icy Veins)"
L["rm.tbc.mage.fire.icyveins.Description"] = "Fuego según Icy Veins, elegida cuando Fuego es tu árbol de talentos principal. Piroexplosión abre el combate una vez aprendida, Agostar mejorado mantiene cinco acumulaciones de Vulnerabilidad al fuego, Bola de Fuego hace de relleno y Explosión de Fuego es para moverse; Ola explosiva, Aliento de dragón y Fogonazo contra tres o más enemigos. Recordatorios: Armadura de arrabio, de mago o de hielo, Combustión con el objetivo por debajo del 20 % de salud, gema de maná, Evocación y las utilidades de mago compartidas."
L["rm.tbc.mage.fire.wowhead.Name"] = "Fuego (Wowhead)"
L["rm.tbc.mage.fire.wowhead.Description"] = "Fuego según Wowhead y simulador. Como la rotación integrada de Fuego de Icy Veins, pero intercala Explosión de Fuego siempre que está lista mientras estás quieto (más daño, más maná) y abre con Bola de Fuego en lugar de Piroexplosión. Una alternativa a la rotación integrada de Fuego de Icy Veins recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad."
L["rm.tbc.mage.frost.Name"] = "Escarcha"
L["rm.tbc.mage.frost.Description"] = "Escarcha del nivel 1 al 70, y la opción predeterminada del mago antes de los talentos. Descarga de Escarcha (Bola de Fuego antes del nivel 4), Nova de Escarcha cuando algo te golpea, Cono de frío con Ventisca o Deflagración Arcana cuando hay tres o más enemigos trabados en combate, Lanza de hielo sobre objetivos congelados y en movimiento, y varita cuando te quedas sin maná. Recordatorios: armadura, Intelecto Arcano, gema de maná, Evocación, Contrahechizo, Robar hechizo, Barrera de hielo, Venas heladas, Mordedura de frío y elemental de agua. Traslación, Bloque de hielo, el kiteo y la elección de objetivo quedan a tu cargo."
